# रवि एजेंट - प्रोजेक्ट बनाने वाली फ़ाइल (GitHub Actions इसे अपने-आप चलाता है)
import json, os
FILES = json.loads(r'''{"build.gradle.kts": "plugins {\n    id(\"com.android.application\") version \"8.5.2\" apply false\n    id(\"org.jetbrains.kotlin.android\") version \"1.9.24\" apply false\n}\n", "settings.gradle.kts": "pluginManagement {\n    repositories { google(); mavenCentral(); gradlePluginPortal() }\n}\ndependencyResolutionManagement {\n    repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS)\n    repositories { google(); mavenCentral() }\n}\nrootProject.name = \"RaviAgent\"\ninclude(\":app\")\n", "gradle.properties": "org.gradle.jvmargs=-Xmx3g -Dfile.encoding=UTF-8\nandroid.nonTransitiveRClass=true\nkotlin.code.style=official\n", "app/build.gradle.kts": "plugins {\n    id(\"com.android.application\")\n    id(\"org.jetbrains.kotlin.android\")\n}\n\nandroid {\n    namespace = \"com.ravi.agent\"\n    compileSdk = 34\n\n    defaultConfig {\n        applicationId = \"com.ravi.agent\"\n        minSdk = 26\n        targetSdk = 34\n        versionCode = 1\n        versionName = \"1.0\"\n    }\n\n    compileOptions {\n        sourceCompatibility = JavaVersion.VERSION_17\n        targetCompatibility = JavaVersion.VERSION_17\n    }\n    kotlinOptions { jvmTarget = \"17\" }\n}\n", "app/src/main/AndroidManifest.xml": "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\">\n\n    <uses-permission android:name=\"android.permission.INTERNET\" />\n    <uses-permission android:name=\"android.permission.RECORD_AUDIO\" />\n    <uses-permission android:name=\"android.permission.QUERY_ALL_PACKAGES\" />\n\n    <queries>\n        <intent><action android:name=\"android.speech.RecognitionService\" /></intent>\n        <intent><action android:name=\"android.intent.action.TTS_SERVICE\" /></intent>\n    </queries>\n\n    <application\n        android:label=\"@string/app_name\"\n        android:theme=\"@android:style/Theme.DeviceDefault.NoActionBar\"\n        android:allowBackup=\"false\">\n\n        <activity\n            android:name=\".MainActivity\"\n            android:exported=\"true\"\n            android:launchMode=\"singleTask\"\n            android:windowSoftInputMode=\"adjustResize\">\n            <intent-filter>\n                <action android:name=\"android.intent.action.MAIN\" />\n                <category android:name=\"android.intent.category.LAUNCHER\" />\n            </intent-filter>\n        </activity>\n\n        <service\n            android:name=\".AgentService\"\n            android:exported=\"true\"\n            android:label=\"@string/app_name\"\n            android:permission=\"android.permission.BIND_ACCESSIBILITY_SERVICE\">\n            <intent-filter>\n                <action android:name=\"android.accessibilityservice.AccessibilityService\" />\n            </intent-filter>\n            <meta-data\n                android:name=\"android.accessibilityservice\"\n                android:resource=\"@xml/accessibility_config\" />\n        </service>\n    </application>\n</manifest>\n", "app/src/main/java/com/ravi/agent/MainActivity.kt": "package com.ravi.agent\n\nimport android.Manifest\nimport android.app.Activity\nimport android.app.AlertDialog\nimport android.content.Intent\nimport android.content.pm.PackageManager\nimport android.graphics.Color\nimport android.net.Uri\nimport android.os.Bundle\nimport android.provider.Settings\nimport android.speech.RecognitionListener\nimport android.speech.RecognizerIntent\nimport android.speech.SpeechRecognizer\nimport android.view.Gravity\nimport android.view.View\nimport android.view.ViewGroup\nimport android.view.inputmethod.EditorInfo\nimport android.widget.Button\nimport android.widget.EditText\nimport android.widget.LinearLayout\nimport android.widget.ScrollView\nimport android.widget.TextView\n\nclass MainActivity : Activity() {\n    private lateinit var logView: TextView\n    private lateinit var scroll: ScrollView\n    private lateinit var status: TextView\n    private lateinit var input: EditText\n    private lateinit var confirmBar: LinearLayout\n    private lateinit var confirmText: TextView\n    private lateinit var setupRow: LinearLayout\n    private var recognizer: SpeechRecognizer? = null\n    private val MATCH = ViewGroup.LayoutParams.MATCH_PARENT\n    private val WRAP = ViewGroup.LayoutParams.WRAP_CONTENT\n\n    private fun dp(v: Int) = (v * resources.displayMetrics.density).toInt()\n\n    private fun btn(label: String, onClick: () -> Unit): Button {\n        val b = Button(this)\n        b.text = label\n        b.isAllCaps = false\n        b.setOnClickListener { onClick() }\n        return b\n    }\n\n    private fun weighted() = LinearLayout.LayoutParams(0, WRAP, 1f)\n\n    override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n        Bridge.activity = this\n\n        val root = LinearLayout(this)\n        root.orientation = LinearLayout.VERTICAL\n        root.setBackgroundColor(Color.parseColor(\"#0F1720\"))\n        root.setPadding(dp(12), dp(32), dp(12), dp(12))\n\n        val faceLp = LinearLayout.LayoutParams(dp(170), dp(170))\n        faceLp.gravity = Gravity.CENTER_HORIZONTAL\n        root.addView(FaceView(this), faceLp)\n\n        status = TextView(this)\n        status.setTextColor(Color.parseColor(\"#8DA2B5\"))\n        status.gravity = Gravity.CENTER\n        status.text = \"तैयार\"\n        root.addView(status, LinearLayout.LayoutParams(MATCH, WRAP))\n\n        setupRow = LinearLayout(this)\n        setupRow.orientation = LinearLayout.HORIZONTAL\n        setupRow.addView(btn(\"स्क्रीन कंट्रोल चालू करें\") {\n            startActivity(Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS))\n        }, weighted())\n        setupRow.addView(btn(\"ऐप जानकारी\") {\n            startActivity(Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS, Uri.parse(\"package:$packageName\")))\n        }, weighted())\n        root.addView(setupRow, LinearLayout.LayoutParams(MATCH, WRAP))\n\n        scroll = ScrollView(this)\n        logView = TextView(this)\n        logView.setTextColor(Color.parseColor(\"#E8EEF4\"))\n        logView.textSize = 15f\n        logView.setPadding(dp(4), dp(8), dp(4), dp(8))\n        scroll.addView(logView)\n        root.addView(scroll, LinearLayout.LayoutParams(MATCH, 0, 1f))\n\n        confirmBar = LinearLayout(this)\n        confirmBar.orientation = LinearLayout.VERTICAL\n        confirmBar.setBackgroundColor(Color.parseColor(\"#3A2A10\"))\n        confirmBar.setPadding(dp(10), dp(10), dp(10), dp(10))\n        confirmBar.visibility = View.GONE\n        confirmText = TextView(this)\n        confirmText.setTextColor(Color.WHITE)\n        confirmText.textSize = 16f\n        confirmBar.addView(confirmText)\n        val yn = LinearLayout(this)\n        yn.orientation = LinearLayout.HORIZONTAL\n        yn.addView(btn(\"हाँ, करो\") { answer(true) }, weighted())\n        yn.addView(btn(\"नहीं\") { answer(false) }, weighted())\n        confirmBar.addView(yn)\n        root.addView(confirmBar, LinearLayout.LayoutParams(MATCH, WRAP))\n\n        val row = LinearLayout(this)\n        row.orientation = LinearLayout.HORIZONTAL\n        input = EditText(this)\n        input.hint = \"काम बताइए…\"\n        input.setHintTextColor(Color.parseColor(\"#8DA2B5\"))\n        input.setTextColor(Color.WHITE)\n        input.setSingleLine()\n        input.imeOptions = EditorInfo.IME_ACTION_SEND\n        input.setOnEditorActionListener { _, _, _ -> sendTyped(); true }\n        row.addView(input, weighted())\n        row.addView(btn(\"🎤\") { listen() })\n        row.addView(btn(\"➤\") { sendTyped() })\n        root.addView(row, LinearLayout.LayoutParams(MATCH, WRAP))\n\n        val row2 = LinearLayout(this)\n        row2.orientation = LinearLayout.HORIZONTAL\n        row2.addView(btn(\"⚙ सेटिंग\") { settings() }, weighted())\n        row2.addView(btn(\"⏹ रुको\") { AgentService.instance?.stop() }, weighted())\n        root.addView(row2, LinearLayout.LayoutParams(MATCH, WRAP))\n\n        setContentView(root)\n        addLog(\"नमस्ते! 🎤 दबाकर या लिखकर काम बताइए।\\nपहली बार: ⚙ सेटिंग में Gemini key डालिए और ऊपर के बटन से स्क्रीन कंट्रोल चालू कीजिए।\")\n        handleIntent(intent)\n    }\n\n    override fun onResume() {\n        super.onResume()\n        setupRow.visibility = if (AgentService.instance == null) View.VISIBLE else View.GONE\n    }\n\n    override fun onNewIntent(intent: Intent?) {\n        super.onNewIntent(intent)\n        if (intent != null) {\n            setIntent(intent)\n            handleIntent(intent)\n        }\n    }\n\n    override fun onDestroy() {\n        Bridge.activity = null\n        recognizer?.destroy()\n        super.onDestroy()\n    }\n\n    private fun handleIntent(i: Intent?) {\n        val q = i?.getStringExtra(\"confirm\") ?: return\n        i?.removeExtra(\"confirm\")\n        confirmText.text = \"क्या मैं यह करूँ?\\n$q\"\n        confirmBar.visibility = View.VISIBLE\n    }\n\n    private fun answer(yes: Boolean) {\n        confirmBar.visibility = View.GONE\n        Bridge.reply(yes)\n        moveTaskToBack(true)  // वापस उसी ऐप पर जहाँ एजेंट काम कर रहा था\n    }\n\n    fun addLog(msg: String) {\n        logView.append(msg + \"\\n\\n\")\n        scroll.post { scroll.fullScroll(View.FOCUS_DOWN) }\n    }\n\n    fun setStatus(s: String) { status.text = s }\n\n    private fun sendTyped() {\n        val t = input.text.toString().trim()\n        if (t.isNotEmpty()) { input.setText(\"\"); submit(t) }\n    }\n\n    private fun submit(text: String) {\n        addLog(\"आप: $text\")\n        val s = AgentService.instance\n        if (s == null) { addLog(\"पहले स्क्रीन कंट्रोल चालू कीजिए (ऊपर का बटन)।\"); return }\n        if (Prefs.key(this).isBlank()) { addLog(\"पहले ⚙ सेटिंग में Gemini key डालिए।\"); return }\n        s.startGoal(text)\n    }\n\n    private fun listen() {\n        if (checkSelfPermission(Manifest.permission.RECORD_AUDIO) != PackageManager.PERMISSION_GRANTED) {\n            requestPermissions(arrayOf(Manifest.permission.RECORD_AUDIO), 1)\n            return\n        }\n        if (!SpeechRecognizer.isRecognitionAvailable(this)) {\n            addLog(\"इस फ़ोन में आवाज़ पहचान उपलब्ध नहीं है, टाइप कीजिए।\")\n            return\n        }\n        recognizer?.destroy()\n        val r = SpeechRecognizer.createSpeechRecognizer(this)\n        r.setRecognitionListener(object : RecognitionListener {\n            override fun onReadyForSpeech(p: Bundle?) { setStatus(\"बोलिए…\") }\n            override fun onBeginningOfSpeech() {}\n            override fun onRmsChanged(v: Float) {}\n            override fun onBufferReceived(b: ByteArray?) {}\n            override fun onEndOfSpeech() { setStatus(\"समझ रहा हूँ…\") }\n            override fun onError(e: Int) { setStatus(\"तैयार\"); addLog(\"आवाज़ साफ़ नहीं आई, फिर बोलिए।\") }\n            override fun onResults(res: Bundle?) {\n                setStatus(\"तैयार\")\n                val t = res?.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION)?.firstOrNull()\n                if (!t.isNullOrBlank()) submit(t)\n            }\n            override fun onPartialResults(p: Bundle?) {}\n            override fun onEvent(t: Int, p: Bundle?) {}\n        })\n        val i = Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH)\n        i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL, RecognizerIntent.LANGUAGE_MODEL_FREE_FORM)\n        i.putExtra(RecognizerIntent.EXTRA_LANGUAGE, \"hi-IN\")\n        r.startListening(i)\n        recognizer = r\n    }\n\n    override fun onRequestPermissionsResult(code: Int, perms: Array<out String>, results: IntArray) {\n        super.onRequestPermissionsResult(code, perms, results)\n        if (results.isNotEmpty() && results[0] == PackageManager.PERMISSION_GRANTED) listen()\n    }\n\n    private fun settings() {\n        val box = LinearLayout(this)\n        box.orientation = LinearLayout.VERTICAL\n        box.setPadding(dp(16), dp(8), dp(16), 0)\n        val k = EditText(this)\n        k.hint = \"Gemini API key\"\n        k.setText(Prefs.key(this))\n        k.setSingleLine()\n        val m = EditText(this)\n        m.hint = \"मॉडल का नाम\"\n        m.setText(Prefs.model(this))\n        m.setSingleLine()\n        box.addView(k)\n        box.addView(m)\n        AlertDialog.Builder(this)\n            .setTitle(\"सेटिंग\")\n            .setView(box)\n            .setPositiveButton(\"सेव\") { _, _ ->\n                val model = m.text.toString().trim().ifBlank { \"gemini-2.5-flash\" }\n                Prefs.save(this, k.text.toString().trim(), model)\n                addLog(\"सेटिंग सेव हो गई।\")\n            }\n            .setNegativeButton(\"रद्द\", null)\n            .show()\n    }\n}\n", "app/src/main/java/com/ravi/agent/AgentService.kt": "package com.ravi.agent\n\nimport android.accessibilityservice.AccessibilityService\nimport android.accessibilityservice.GestureDescription\nimport android.content.Intent\nimport android.graphics.Path\nimport android.graphics.Rect\nimport android.os.Build\nimport android.os.Bundle\nimport android.speech.tts.TextToSpeech\nimport android.speech.tts.UtteranceProgressListener\nimport android.view.accessibility.AccessibilityEvent\nimport android.view.accessibility.AccessibilityNodeInfo\nimport org.json.JSONObject\nimport java.util.Locale\nimport java.util.concurrent.CountDownLatch\nimport java.util.concurrent.Executors\nimport java.util.concurrent.TimeUnit\n\nclass AgentService : AccessibilityService() {\n\n    companion object {\n        @Volatile var instance: AgentService? = null\n        const val MAX_STEPS = 30\n        val RISKY = Regex(\"(?i)(send|post|share|submit|delete|भेज|पोस्ट|डिलीट|हटा)\")\n        // पैसे वाले कदम: पूछना नहीं, सीधे बंद\n        val MONEY = Regex(\"(?i)(\\\\bpay\\\\b|payment|buy now|place order|order now|checkout|transfer|send money|upi|\\\\bpin\\\\b|\\\\bsell\\\\b|भुगतान|पेमेंट|खरीदें|ऑर्डर करें|ट्रांसफर|पैसे|बेचें)\")\n        // बैंकिंग, पेमेंट, वॉलेट, ट्रेडिंग ऐप (पैकेज या नाम में ये शब्द हों तो ऐप बंद)\n        val MONEY_APPS = listOf(\n            \"bank\", \"बैंक\", \"paytm\", \"phonepe\", \"gpay\", \"nbu.paisa\", \"google pay\", \"bhim\", \"razorpay\",\n            \"mobikwik\", \"freecharge\", \"dreamplug\", \"amazon pay\", \"wallet\", \"वॉलेट\", \"zerodha\", \"kite\",\n            \"groww\", \"upstox\", \"angelone\", \"angel one\", \"5paisa\", \"dhan\", \"demat\", \"trading\", \"sbi\",\n            \"hdfc\", \"icici\", \"axis\", \"kotak\", \"pnb\", \"idfc\", \"yesbank\", \"indusind\", \"canara\", \"npci\"\n        )\n\n        val SYSTEM = \"\"\"\nYou control an Android phone for its owner through the accessibility API. Each turn you receive the owner's goal, the steps done so far, and the current screen as a numbered list of elements.\nReply with exactly ONE JSON object and nothing else:\n{\"action\": \"tap|type|scroll|back|home|open_app|wait|ask|finish\",\n \"index\": number (element number, for tap and type),\n \"text\": string (for type),\n \"submit\": true or false (for type: press search/enter after typing),\n \"direction\": \"up\" or \"down\" (for scroll),\n \"app\": string (for open_app: the app name as shown on the phone, in English),\n \"reason\": short explanation in Hindi,\n \"sensitive\": true or false,\n \"money\": true or false,\n \"say\": short sentence in Hindi to speak aloud (only for ask and finish, otherwise empty)}\nRules:\n- Set sensitive=true for any step that sends a message or email, posts publicly, deletes data, or changes account settings. The owner will be asked to confirm before it runs.\n- NEVER open or operate banking, payment, UPI, wallet, trading, demat or share-market apps, and NEVER perform any step that moves, spends or invests money (paying, buying, placing an order, transferring, selling). If the goal needs that, set money=true, use action ask, and tell the owner in Hindi to do that step personally.\n- Never type passwords, OTPs, card numbers or UPI PINs. Use action ask and tell the owner to enter them personally, then continue after they reply.\n- Use open_app to start an app instead of hunting for icons.\n- If the screen is still loading, use wait. If an action did not work, try a different approach; never repeat the same failing action more than twice.\n- If you need information from the owner, use ask with the question in say.\n- When the goal is fully done, use finish and put a short Hindi summary of the result in say.\n- If the goal is only a question or chat and needs no phone action, answer it directly with finish.\n- Never invent screen elements. Use only the index numbers given.\n\"\"\".trimIndent()\n    }\n\n    private var tts: TextToSpeech? = null\n    private var ttsReady = false\n    private val worker = Executors.newSingleThreadExecutor()\n    @Volatile private var stopFlag = false\n    @Volatile var busy = false\n    private val history = ArrayList<String>()\n    private var nodes = ArrayList<AccessibilityNodeInfo>()\n\n    override fun onServiceConnected() {\n        instance = this\n        tts = TextToSpeech(this) { status ->\n            if (status == TextToSpeech.SUCCESS) {\n                val r = tts?.setLanguage(Locale(\"hi\", \"IN\")) ?: TextToSpeech.LANG_NOT_SUPPORTED\n                if (r < 0) tts?.setLanguage(Locale.getDefault())\n                tts?.setOnUtteranceProgressListener(object : UtteranceProgressListener() {\n                    override fun onStart(id: String?) { Bridge.speaking = true }\n                    override fun onDone(id: String?) { Bridge.speaking = false }\n                    @Deprecated(\"Deprecated in Java\")\n                    override fun onError(id: String?) { Bridge.speaking = false }\n                })\n                ttsReady = true\n            }\n        }\n        Bridge.log(\"✅ स्क्रीन कंट्रोल चालू है।\")\n    }\n\n    override fun onAccessibilityEvent(event: AccessibilityEvent?) {}\n    override fun onInterrupt() {}\n\n    override fun onUnbind(intent: Intent?): Boolean {\n        instance = null\n        tts?.shutdown()\n        return super.onUnbind(intent)\n    }\n\n    // ---------- बाहर से इस्तेमाल ----------\n    fun startGoal(goal: String) {\n        if (busy) { Bridge.log(\"पिछला काम चल रहा है। रोकना हो तो ⏹ दबाइए।\"); return }\n        worker.execute { runGoal(goal) }\n    }\n\n    fun stop() { stopFlag = true }\n\n    fun speak(text: String) {\n        if (ttsReady) tts?.speak(text, TextToSpeech.QUEUE_FLUSH, null, \"u\" + System.nanoTime())\n    }\n\n    private fun say(text: String) {\n        Bridge.log(\"🤖 $text\")\n        speak(text)\n        history.add(\"एजेंट: $text\")\n    }\n\n    // ---------- एजेंट लूप ----------\n    private fun runGoal(goal: String) {\n        busy = true\n        stopFlag = false\n        history.add(\"यूज़र: $goal\")\n        while (history.size > 12) history.removeAt(0)\n        val done = ArrayList<String>()\n        var lastKey = \"\"\n        var repeat = 0\n        try {\n            for (step in 1..MAX_STEPS) {\n                if (stopFlag) { say(\"ठीक है, रुक गया।\"); break }\n                Bridge.state(\"काम चल रहा है… कदम $step\")\n                val curPkg = rootInActiveWindow?.packageName?.toString()\n                if (isMoneyApp(curPkg)) {\n                    performGlobalAction(GLOBAL_ACTION_HOME)\n                    say(\"यह पैसे या बैंकिंग वाला ऐप है। सुरक्षा के लिए मैं इसमें कुछ नहीं करता और इसकी स्क्रीन भी नहीं पढ़ता। यह काम आप खुद कीजिए।\")\n                    break\n                }\n                val screen = snapshot()\n                val prompt = \"पिछली बातचीत:\\n\" + history.takeLast(8).joinToString(\"\\n\") +\n                    \"\\n\\nमौजूदा लक्ष्य: $goal\\n\\nअब तक के कदम:\\n\" +\n                    (if (done.isEmpty()) \"(कोई नहीं)\" else done.takeLast(12).joinToString(\"\\n\")) +\n                    \"\\n\\nअभी की स्क्रीन:\\n$screen\"\n                val raw = Gemini.call(Prefs.key(this), Prefs.model(this), SYSTEM, prompt)\n                val a = JSONObject(raw.trim().removePrefix(\"```json\").removePrefix(\"```\").removeSuffix(\"```\").trim())\n                val act = a.optString(\"action\")\n                val idx = a.optInt(\"index\", -1)\n                val text = a.optString(\"text\")\n                val reason = a.optString(\"reason\")\n                val sayText = a.optString(\"say\")\n                Bridge.log(\"• $act ${if (reason.isNotBlank()) \"— $reason\" else \"\"}\")\n\n                val key = \"$act|$idx|$text|${a.optString(\"app\")}\"\n                if (key == lastKey) repeat++ else { repeat = 0; lastKey = key }\n                if (repeat >= 3) { say(\"मैं एक ही जगह अटक गया हूँ। आप बताइए आगे क्या करूँ।\"); break }\n\n                if (act == \"finish\") { say(sayText.ifBlank { \"काम हो गया।\" }); break }\n                if (act == \"ask\") { say(sayText.ifBlank { \"मुझे आपकी मदद चाहिए।\" }); break }\n\n                var needConfirm = a.optBoolean(\"sensitive\", false)\n                var money = a.optBoolean(\"money\", false)\n                if (act == \"tap\" || act == \"type\") {\n                    val n = nodes.getOrNull(idx)\n                    val label = ((n?.text ?: \"\").toString() + \" \" + (n?.contentDescription ?: \"\").toString()).trim()\n                    if (label.length < 40 && MONEY.containsMatchIn(label)) money = true\n                    if (label.length < 30 && RISKY.containsMatchIn(label)) needConfirm = true\n                }\n                if (act == \"open_app\" && isMoneyApp(a.optString(\"app\"))) money = true\n                if (money) {\n                    done.add(\"पैसे से जुड़ा कदम रोका गया\")\n                    say(\"यह पैसे से जुड़ा कदम है। इसे मैं नहीं करूँगा, आप खुद कर लीजिए।\")\n                    break\n                }\n                if (needConfirm) {\n                    val q = reason.ifBlank { \"यह कदम\" }\n                    if (!confirm(q)) { done.add(\"यूज़र ने '$q' करने से मना कर दिया\"); say(\"ठीक है, यह नहीं करता।\"); break }\n                }\n\n                val result = when (act) {\n                    \"tap\" -> doTap(idx)\n                    \"type\" -> doType(idx, text, a.optBoolean(\"submit\", false))\n                    \"scroll\" -> doScroll(a.optString(\"direction\", \"down\"))\n                    \"back\" -> if (performGlobalAction(GLOBAL_ACTION_BACK)) \"ok\" else \"fail\"\n                    \"home\" -> if (performGlobalAction(GLOBAL_ACTION_HOME)) \"ok\" else \"fail\"\n                    \"open_app\" -> doOpenApp(a.optString(\"app\"))\n                    \"wait\" -> { Thread.sleep(2000); \"ok\" }\n                    else -> \"अनजान action\"\n                }\n                done.add(\"$step. $act ${if (idx >= 0) \"[$idx]\" else \"\"} $text ${a.optString(\"app\")} → $result\")\n                Thread.sleep(1500)\n            }\n        } catch (e: Exception) {\n            say(\"गड़बड़ी हुई: ${e.message}\")\n        } finally {\n            busy = false\n            Bridge.state(\"तैयार\")\n        }\n    }\n\n    private fun isMoneyApp(pkg: String?): Boolean {\n        if (pkg.isNullOrBlank()) return false\n        var label = \"\"\n        try {\n            label = packageManager.getApplicationLabel(packageManager.getApplicationInfo(pkg, 0)).toString()\n        } catch (e: Exception) {\n        }\n        val s = (pkg + \" \" + label).lowercase()\n        return MONEY_APPS.any { s.contains(it) }\n    }\n\n    private fun confirm(q: String): Boolean {\n        val latch = CountDownLatch(1)\n        Bridge.answer = false\n        Bridge.pending = latch\n        speak(\"क्या मैं यह करूँ? $q\")\n        val i = Intent(this, MainActivity::class.java)\n            .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_REORDER_TO_FRONT or Intent.FLAG_ACTIVITY_SINGLE_TOP)\n            .putExtra(\"confirm\", q)\n        startActivity(i)\n        val got = latch.await(120, TimeUnit.SECONDS)\n        Bridge.pending = null\n        return got && Bridge.answer\n    }\n\n    // ---------- स्क्रीन पढ़ना ----------\n    private fun snapshot(): String {\n        var root: AccessibilityNodeInfo? = null\n        for (i in 1..3) {\n            root = rootInActiveWindow\n            if (root != null) break\n            Thread.sleep(500)\n        }\n        nodes = ArrayList()\n        if (root == null) return \"(स्क्रीन पढ़ नहीं पाया)\"\n        val sb = StringBuilder()\n        sb.append(\"ऐप: \").append(root.packageName).append(\"\\n\")\n        walk(root, sb)\n        return sb.toString().take(9000)\n    }\n\n    private fun walk(n: AccessibilityNodeInfo?, sb: StringBuilder) {\n        if (n == null || nodes.size >= 150) return\n        if (n.isVisibleToUser) {\n            val text = (n.text ?: \"\").toString().replace(\"\\n\", \" \").take(80)\n            val desc = (n.contentDescription ?: \"\").toString().replace(\"\\n\", \" \").take(80)\n            val hint = (n.hintText ?: \"\").toString().take(40)\n            val interactive = n.isClickable || n.isEditable || n.isScrollable || n.isCheckable\n            if (text.isNotBlank() || desc.isNotBlank() || interactive) {\n                val idx = nodes.size\n                nodes.add(n)\n                sb.append(\"[\").append(idx).append(\"] \")\n                sb.append((n.className ?: \"\").toString().substringAfterLast('.'))\n                if (n.isPassword) sb.append(\" (पासवर्ड)\")\n                else if (text.isNotBlank()) sb.append(\" \\\"\").append(text).append(\"\\\"\")\n                if (desc.isNotBlank()) sb.append(\" desc=\\\"\").append(desc).append(\"\\\"\")\n                if (hint.isNotBlank()) sb.append(\" hint=\\\"\").append(hint).append(\"\\\"\")\n                if (n.isClickable) sb.append(\" click\")\n                if (n.isEditable) sb.append(\" edit\")\n                if (n.isScrollable) sb.append(\" scroll\")\n                if (n.isChecked) sb.append(\" checked\")\n                sb.append(\"\\n\")\n            }\n        }\n        for (i in 0 until n.childCount) walk(n.getChild(i), sb)\n    }\n\n    // ---------- काम करना ----------\n    private fun doTap(i: Int): String {\n        val n = nodes.getOrNull(i) ?: return \"गलत नंबर\"\n        var cur: AccessibilityNodeInfo? = n\n        while (cur != null && !cur.isClickable) cur = cur.parent\n        if (cur != null && cur.performAction(AccessibilityNodeInfo.ACTION_CLICK)) return \"ok\"\n        val r = Rect()\n        n.getBoundsInScreen(r)\n        return if (tapXY(r.centerX().toFloat(), r.centerY().toFloat())) \"ok\" else \"fail\"\n    }\n\n    private fun tapXY(x: Float, y: Float): Boolean {\n        val p = Path()\n        p.moveTo(x, y)\n        val g = GestureDescription.Builder()\n            .addStroke(GestureDescription.StrokeDescription(p, 0, 80)).build()\n        return dispatchGesture(g, null, null)\n    }\n\n    private fun doType(i: Int, text: String, submit: Boolean): String {\n        val n = nodes.getOrNull(i) ?: return \"गलत नंबर\"\n        if (n.isPassword) return \"पासवर्ड वाली जगह है, मैं नहीं भरता\"\n        n.performAction(AccessibilityNodeInfo.ACTION_FOCUS)\n        n.performAction(AccessibilityNodeInfo.ACTION_CLICK)\n        val b = Bundle()\n        b.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE, text)\n        val ok = n.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT, b)\n        if (ok && submit && Build.VERSION.SDK_INT >= 30) {\n            Thread.sleep(500)\n            n.performAction(AccessibilityNodeInfo.AccessibilityAction.ACTION_IME_ENTER.id)\n        }\n        return if (ok) \"ok\" else \"fail\"\n    }\n\n    private fun findScrollable(n: AccessibilityNodeInfo?): AccessibilityNodeInfo? {\n        if (n == null) return null\n        if (n.isScrollable) return n\n        for (i in 0 until n.childCount) {\n            val r = findScrollable(n.getChild(i))\n            if (r != null) return r\n        }\n        return null\n    }\n\n    private fun doScroll(dir: String): String {\n        val root = rootInActiveWindow ?: return \"स्क्रीन नहीं मिली\"\n        val target = findScrollable(root)\n        val act = if (dir == \"up\") AccessibilityNodeInfo.ACTION_SCROLL_BACKWARD else AccessibilityNodeInfo.ACTION_SCROLL_FORWARD\n        if (target != null && target.performAction(act)) return \"ok\"\n        val dm = resources.displayMetrics\n        val x = dm.widthPixels / 2f\n        val hi = dm.heightPixels * 0.7f\n        val lo = dm.heightPixels * 0.3f\n        val p = Path()\n        if (dir == \"up\") { p.moveTo(x, lo); p.lineTo(x, hi) } else { p.moveTo(x, hi); p.lineTo(x, lo) }\n        val g = GestureDescription.Builder()\n            .addStroke(GestureDescription.StrokeDescription(p, 0, 300)).build()\n        return if (dispatchGesture(g, null, null)) \"ok\" else \"fail\"\n    }\n\n    private fun doOpenApp(name: String): String {\n        if (name.isBlank()) return \"ऐप का नाम नहीं मिला\"\n        val pm = packageManager\n        val q = name.lowercase()\n        val apps = pm.getInstalledApplications(0)\n        var pkg: String? = apps.firstOrNull { it.packageName.equals(name, true) }?.packageName\n        if (pkg == null) {\n            pkg = apps.firstOrNull {\n                pm.getLaunchIntentForPackage(it.packageName) != null &&\n                    pm.getApplicationLabel(it).toString().lowercase().contains(q)\n            }?.packageName\n        }\n        if (pkg == null) return \"ऐप नहीं मिला: $name\"\n        if (isMoneyApp(pkg)) return \"blocked\"\n        val i = pm.getLaunchIntentForPackage(pkg) ?: return \"ऐप खुल नहीं सका\"\n        i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)\n        startActivity(i)\n        return \"ok\"\n    }\n}\n", "app/src/main/java/com/ravi/agent/Prefs.kt": "package com.ravi.agent\n\nimport android.content.Context\n\nobject Prefs {\n    private fun p(c: Context) = c.getSharedPreferences(\"ravi\", Context.MODE_PRIVATE)\n    fun key(c: Context): String = p(c).getString(\"key\", \"\") ?: \"\"\n    fun model(c: Context): String = p(c).getString(\"model\", \"gemini-2.5-flash\") ?: \"gemini-2.5-flash\"\n    fun save(c: Context, key: String, model: String) {\n        p(c).edit().putString(\"key\", key).putString(\"model\", model).apply()\n    }\n}\n", "app/src/main/java/com/ravi/agent/Bridge.kt": "package com.ravi.agent\n\nimport android.os.Handler\nimport android.os.Looper\nimport java.util.concurrent.CountDownLatch\n\n/** सर्विस और स्क्रीन के बीच साझा स्थिति। */\nobject Bridge {\n    @Volatile var speaking = false\n    @Volatile var activity: MainActivity? = null\n    @Volatile var pending: CountDownLatch? = null\n    @Volatile var answer = false\n    val main = Handler(Looper.getMainLooper())\n\n    fun log(msg: String) { main.post { activity?.addLog(msg) } }\n    fun state(s: String) { main.post { activity?.setStatus(s) } }\n    fun reply(yes: Boolean) { answer = yes; pending?.countDown() }\n}\n", "app/src/main/java/com/ravi/agent/Gemini.kt": "package com.ravi.agent\n\nimport org.json.JSONArray\nimport org.json.JSONObject\nimport java.net.HttpURLConnection\nimport java.net.URL\n\nobject Gemini {\n    fun call(key: String, model: String, system: String, user: String): String {\n        if (key.isBlank()) throw RuntimeException(\"पहले सेटिंग में Gemini key डालिए\")\n        val body = JSONObject()\n            .put(\"systemInstruction\", JSONObject().put(\"parts\", JSONArray().put(JSONObject().put(\"text\", system))))\n            .put(\n                \"contents\",\n                JSONArray().put(\n                    JSONObject().put(\"role\", \"user\")\n                        .put(\"parts\", JSONArray().put(JSONObject().put(\"text\", user)))\n                )\n            )\n            .put(\n                \"generationConfig\",\n                JSONObject().put(\"responseMimeType\", \"application/json\").put(\"temperature\", 0.2)\n            )\n        var lastErr = \"\"\n        for (wait in longArrayOf(0L, 3000L, 8000L)) {  // मुफ़्त key पर 429/503 आम हैं\n            if (wait > 0) Thread.sleep(wait)\n            val c = URL(\"https://generativelanguage.googleapis.com/v1beta/models/$model:generateContent\")\n                .openConnection() as HttpURLConnection\n            c.requestMethod = \"POST\"\n            c.doOutput = true\n            c.connectTimeout = 20000\n            c.readTimeout = 90000\n            c.setRequestProperty(\"Content-Type\", \"application/json\")\n            c.setRequestProperty(\"x-goog-api-key\", key)\n            c.outputStream.use { it.write(body.toString().toByteArray(Charsets.UTF_8)) }\n            val code = c.responseCode\n            val stream = if (code in 200..299) c.inputStream else c.errorStream\n            val txt = stream?.bufferedReader(Charsets.UTF_8)?.readText() ?: \"\"\n            if (code in 200..299) {\n                return JSONObject(txt).getJSONArray(\"candidates\").getJSONObject(0)\n                    .getJSONObject(\"content\").getJSONArray(\"parts\").getJSONObject(0).getString(\"text\")\n            }\n            lastErr = \"$code ${txt.take(200)}\"\n            if (code != 429 && code != 503) break\n        }\n        throw RuntimeException(\"Gemini से जवाब नहीं मिला: $lastErr\")\n    }\n}\n", "app/src/main/java/com/ravi/agent/FaceView.kt": "package com.ravi.agent\n\nimport android.content.Context\nimport android.graphics.Canvas\nimport android.graphics.Color\nimport android.graphics.Paint\nimport android.graphics.RectF\nimport android.view.View\nimport kotlin.math.abs\nimport kotlin.math.max\nimport kotlin.math.sin\n\n/** बोलता चेहरा: Bridge.speaking चालू होने पर मुँह हिलता है। */\nclass FaceView(ctx: Context) : View(ctx) {\n    private val p = Paint(Paint.ANTI_ALIAS_FLAG)\n    private var t = 0f\n    private var level = 0f\n    private var blink = 0f\n\n    private fun oval(c: Canvas, cx: Float, cy: Float, rx: Float, ry: Float, color: Int) {\n        p.style = Paint.Style.FILL\n        p.color = color\n        c.drawOval(RectF(cx - rx, cy - ry, cx + rx, cy + ry), p)\n    }\n\n    override fun onDraw(c: Canvas) {\n        t += 0.016f\n        val u = minOf(width, height) / 100f\n        val ox = (width - 100f * u) / 2f\n        val target = if (Bridge.speaking) 0.35f + 0.3f * abs(sin(t * 14f)) else 0f\n        level += (target - level) * 0.35f\n        if ((t * 10f).toInt() % 45 == 0) blink = 0.12f\n        blink = max(0f, blink - 0.016f)\n\n        c.save()\n        c.translate(ox, sin(t * 1.2f) * u * 0.8f)\n        oval(c, 50f * u, 104f * u, 38f * u, 22f * u, Color.parseColor(\"#24485C\"))\n        p.style = Paint.Style.FILL\n        p.color = Color.parseColor(\"#D9AB85\")\n        c.drawRect(43f * u, 70f * u, 57f * u, 86f * u, p)\n        oval(c, 50f * u, 48f * u, 28f * u, 34f * u, Color.parseColor(\"#F0C9A4\"))\n        p.style = Paint.Style.FILL\n        p.color = Color.parseColor(\"#1A1A22\")\n        c.drawArc(RectF(21f * u, 7f * u, 79f * u, 37f * u), 180f, 180f, true, p)\n\n        val ey = if (blink > 0f) 0.6f else 4.5f\n        for (x in floatArrayOf(38f, 62f)) {\n            oval(c, x * u, 46f * u, 5.5f * u, ey * u, Color.WHITE)\n            if (blink <= 0f) oval(c, x * u, 46f * u, 2.6f * u, 2.6f * u, Color.parseColor(\"#2B1D14\"))\n            p.style = Paint.Style.STROKE\n            p.strokeWidth = u * 1.2f\n            p.color = Color.parseColor(\"#1A1A22\")\n            c.drawLine((x - 6f) * u, 38f * u, (x + 6f) * u, 37f * u, p)\n        }\n        p.style = Paint.Style.STROKE\n        p.strokeWidth = u\n        p.color = Color.parseColor(\"#C08F68\")\n        c.drawLine(50f * u, 50f * u, 48f * u, 58f * u, p)\n        c.drawLine(48f * u, 58f * u, 52f * u, 58f * u, p)\n        oval(c, 50f * u, 65f * u, 8f * u, (1f + level * 9f) * u, Color.parseColor(\"#7A2E2E\"))\n        c.restore()\n        postInvalidateOnAnimation()\n    }\n}\n", "app/src/main/res/xml/accessibility_config.xml": "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<accessibility-service xmlns:android=\"http://schemas.android.com/apk/res/android\"\n    android:accessibilityEventTypes=\"typeAllMask\"\n    android:accessibilityFeedbackType=\"feedbackGeneric\"\n    android:accessibilityFlags=\"flagDefault|flagIncludeNotImportantViews|flagRetrieveInteractiveWindows\"\n    android:canRetrieveWindowContent=\"true\"\n    android:canPerformGestures=\"true\"\n    android:notificationTimeout=\"100\"\n    android:description=\"@string/a11y_desc\" />\n", "app/src/main/res/values/strings.xml": "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<resources>\n    <string name=\"app_name\">रवि एजेंट</string>\n    <string name=\"a11y_desc\">यह सेवा आपके कहने पर स्क्रीन पढ़कर टैप, टाइप और स्क्रॉल करती है।</string>\n</resources>\n"}''')
for path, text in FILES.items():
    d = os.path.dirname(path)
    if d:
        os.makedirs(d, exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        f.write(text)
print("बन गईं", len(FILES), "फ़ाइलें")
